package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.AuthController; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import java.awt.*; public class SignupFrame extends BaseFrame {public SignupFrame(){super("College Sign Up");JPanel p=new JPanel(new GridLayout(0,2,8,8));p.setBorder(BorderFactory.createEmptyBorder(60,160,60,160));JTextField n=new JTextField(),e=new JTextField(),d=new JTextField();JPasswordField a=new JPasswordField(),b=new JPasswordField();for(Object[] x:new Object[][]{{"Username",n},{"Email",e},{"Password",a},{"Confirm Password",b},{"Department",d}}){p.add(new JLabel((String)x[0]));p.add((Component)x[1]);}JButton go=button("Create Account");p.add(go);add(p);go.addActionListener(x->{try{new AuthController().signup(n.getText(),e.getText(),new String(a.getPassword()),new String(b.getPassword()),d.getText());dispose();new DashboardFrame().setVisible(true);}catch(Exception z){DialogUtil.error(this,z.getMessage());}});}}
